            /** @description Sentinela isolada: W, NA, s, XX, ... */
            value_flag: string | null;
            /** @description Leitura da sentinela, em português. */
            value_flag_reason: string | null;
            unit: string | null;
            /** @description Participação no total mundial, em %. NULO quando não é calculável, e nesse caso `share_basis` diz o motivo. Nunca zero por ausência. */
            share_of_world_pct: number | null;
            /** @description Por que o share existe ou não existe. Sempre preenchido, mesmo quando o share é nulo. `ok`: share calculado contra o total mundial da MESMA base e unidade. `incomparable_basis`: existe total mundial para a commodity, mas os países reportam bases diferentes e não somáveis. É o caso das reservas de boro (Turquia em boratos refinados, Chile em ulexita, China em óxido bórico equivalente); o próprio USGS marca o total como `XX`. Dividir um país por esse total produz o tipo de número redondo e falso que circula por aí. `world_total_not_calculable`: o USGS publica o total como `XX`, ou seja, declara-o incalculável. `no_world_total`: não há total mundial publicado para o recorte (comum nas séries só domésticas dos EUA, que a publicação traz com mais anos que a tabela mundial). `is_world_total`: a própria linha é o total mundial, então não há share de si mesma. `value_<flag>` (`value_na`, `value_w`, `value_s`, `value_large`, ...): o país não tem valor numérico; a sentinela publicada está em `value_raw` e o motivo em `value_flag_reason`. */
            share_basis: string;
